mapper.update:
UPDATE mall_market_post
title = #{title}, description = #{description}, price = #{price}, images = #{images}, category = #{category}, status = #{status}, phone = #{phone}, whatsapp = #{whatsapp}, messenger = #{messenger}, telegram = #{telegram}, update_time = NOW()
WHERE post_id = #{postId} AND member_id = #{memberId}

UPDATE mall_market_post
SET comment_count = GREATEST(comment_count - 1, 0)
WHERE post_id = #{postId}

mapper.select:
SELECT p.*, m.nick_name AS member_nickname FROM mall_market_post p LEFT JOIN mall_member m ON m.member_id = p.member_id WHERE p.del_flag = '0'
AND p.title LIKE CONCAT('%', #{title}, '%')
AND p.review_status = #{reviewStatus}
AND p.status = #{status}
ORDER BY p.create_time DESC

SELECT r.*, m.nick_name AS reporter_nickname, CASE r.target_type WHEN 'post' THEN (SELECT title FROM mall_market_post WHERE post_id = r.target_id) WHEN 'comment' THEN (SELECT content FROM mall_market_comment WHERE comment_id = r.target_id) END AS target_title FROM mall_market_report r LEFT JOIN mall_member m ON m.member_id = r.reporter_id WHERE 1=1
AND r.status = #{status}
AND r.target_type = #{targetType}
ORDER BY r.status ASC, r.create_time DESC
